from threetears.evals import Eval

from claims import Claim, decide

def judge_claim(case):
    """The desk's decision on the claim: its outcome and the faults it repairs."""
    decision = decide(Claim.from_row(case))
    return {"outcome": decision.outcome, "repair": list(decision.repair)}


def as_decided(case, out):
    """The claim is decided as the senior technician decided it."""
    return out == case["desk"]

claims = Eval("data/decided.jsonl", runner=judge_claim, grader=[as_decided], k=1)
